def clean(df):
    df = df.drop_duplicates().copy()
    df['Region'] = df['Region'].str.strip().str.title()
    df = df[df['Quantity'] >= 1].copy()
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    return df[df['Category'] == 'Electronics'].groupby('Region')['Revenue'].sum().dropna().to_dict()
